import type { PluginContext } from '../../plugin/types.js';
import type { CodeWriter } from '../../writer/code-writer.js';
import { align, docLines, type Row } from './align.js';
import type { GoPluginOptions } from './index.js';

/** The marker Go tools recognize generated files by (`^// Code generated .* DO NOT EDIT\.$`). */
export const GENERATED_MARKER = 'Code generated by Archon. DO NOT EDIT.';

/** Standard library packages the generated code may use, by the name it refers to them with. */
const STD_IMPORTS: Record<string, string> = {
  context: 'context',
  http: 'net/http',
  json: 'encoding/json',
  time: 'time',
};

/** The generated header as `//` lines: the Go marker, then `output.header`. */
export function headerComment(ctx: PluginContext<GoPluginOptions>): string[] {
  return [GENERATED_MARKER, ...ctx.headerLines('go')].flatMap((l) => l.split('\n')).map((l) => (l === '' ? '//' : `// ${l}`));
}

/**
 * The imports `code` uses: standard packages and `<module>/core` by their `name.` references, plus `extra` (from
 * type mappings). Comments and string literals are ignored.
 */
export function importsFor(code: string, module: string, extra: Iterable<string> = []): string[] {
  const text = code
    .split('\n')
    .filter((line) => !/^\s*\/\//.test(line))
    .join('\n')
    .replace(/"(?:\\.|[^"\\])*"|`[^`]*`/g, '""');
  const used = (name: string) => new RegExp(`(?<![.\\w])${name}\\.`).test(text);
  const out = new Set<string>();
  for (const [name, path] of Object.entries(STD_IMPORTS)) if (used(name)) out.add(path);
  if (used('core')) out.add(`${module}/core`);
  for (const path of extra) out.add(path);
  return [...out];
}

/** A Go source file: header, package clause, imports (standard library first, gofmt-sorted) and `body`. */
export function goSource(ctx: PluginContext<GoPluginOptions>, packageName: string, module: string, body: string, extraImports: Iterable<string> = []): string {
  const w = ctx.writer({ indent: '\t' });
  w.lines(headerComment(ctx));
  w.blank();
  w.line(`package ${packageName}`);
  w.blank();
  const imports = importsFor(body, module, extraImports);
  const std = imports.filter((p) => !p.includes('.') && !p.startsWith(`${module}/`)).sort();
  const others = imports.filter((p) => !std.includes(p)).sort();
  if (imports.length > 0) {
    w.line('import (');
    w.indent(() => {
      for (const p of std) w.line(goString(p));
      if (std.length > 0 && others.length > 0) w.line();
      for (const p of others) w.line(goString(p));
    });
    w.line(')');
    w.blank();
  }
  w.line(body.replace(/\n$/, ''));
  return w.toString();
}

/** A doc comment (nothing for an empty text). */
export function doc(w: CodeWriter, text: string | undefined): void {
  for (const line of docLines(text)) w.line(line === '' ? '//' : `// ${line}`);
}

/** Comment rows for `align` (a doc comment inside a struct or a literal). */
export function docRows(text: string | undefined): Row[] {
  return docLines(text).map((line) => (line === '' ? '//' : `// ${line}`));
}

/** Writes aligned rows at the current indentation. */
export function writeRows(w: CodeWriter, rows: Row[]): void {
  for (const line of align(rows)) w.line(line);
}

/** An entry of a multi-line keyed literal: `key: value,` on one line, or `key: open` + `items` (one per line) + `},`. */
export type KeyedEntry = { key: string; value: string } | { key: string; open: string; items: string[] };

/**
 * Writes the entries of a keyed literal. gofmt aligns the values of consecutive single-line entries; an entry
 * spanning lines breaks the alignment on both sides.
 */
export function writeKeyed(w: CodeWriter, entries: KeyedEntry[]): void {
  let run: Row[] = [];
  const flush = () => {
    writeRows(w, run);
    run = [];
  };
  for (const e of entries) {
    if ('value' in e) {
      run.push([`${e.key}:`, `${e.value},`]);
      continue;
    }
    flush();
    w.line(`${e.key}: ${e.open}`);
    w.indent(() => e.items.forEach((item) => w.line(`${item},`)));
    w.line('},');
  }
  flush();
}

/** A Go interpreted string literal. Invalid UTF-16 (lone surrogates) becomes U+FFFD. */
export function goString(value: string): string {
  let out = '"';
  for (const ch of value) {
    const code = ch.codePointAt(0) as number;
    if (ch === '\\') out += '\\\\';
    else if (ch === '"') out += '\\"';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (code >= 0xd800 && code <= 0xdfff) out += '\\uFFFD';
    else if (code < 0x20 || code === 0x7f) out += `\\x${code.toString(16).padStart(2, '0')}`;
    else out += ch;
  }
  return `${out}"`;
}

/** Whether `name` can be a json struct tag name as written (encoding/json ignores other tag names). */
export function isValidTagName(name: string): boolean {
  if (name === '') return false;
  for (const ch of name) {
    if ('!#$%&()*+-./:;<=>?@[]^_{|}~ '.includes(ch)) continue;
    if (!/[\p{L}\p{Nd}]/u.test(ch)) return false;
  }
  return true;
}
